<script setup lang="ts">
import QrcodeVue from'qrcode.vue'
definePageMeta({layout:'dashboard',middleware:'auth'});useSeoPage('Create link','Create a new managed short link.','/dashboard/links/create')
const{create}=useLinks();const error=ref('');const loading=ref(false);const preview=ref<Record<string,string|boolean>>({custom_alias:'',destination_url:'',title:'',is_active:true});const config=useRuntimeConfig();const shortPreview=computed(()=>`${config.public.shortUrlDomain.replace(/\/$/,'')}/${preview.value.custom_alias||'your-link'}`)
async function submit(payload:Record<string,unknown>){loading.value=true;error.value='';try{const response=await create(payload);await navigateTo(`/dashboard/links/${response.data.id}?created=1`)}catch(e:any){error.value=Object.values(e?.data?.errors||{}).flat().join(' ')||e?.data?.message||'Unable to create link.'}finally{loading.value=false}}
</script>
<template><div class="dashboard-page"><NuxtLink to="/dashboard/links" class="text-xs text-text-muted hover:text-brand">← Back to links</NuxtLink><div class="mt-4"><h1 class="page-title">Create a short link</h1><p class="mt-1 text-sm text-text-secondary">Add context, expiration, and tags now or update them later.</p></div><p v-if="error" class="mt-5 rounded-lg border border-danger-border bg-danger-bg p-4 text-sm text-danger" role="alert">{{ error }}</p><div class="mt-6 grid items-start gap-5 lg:grid-cols-[1.2fr_.8fr]"><LinkForm submit-label="Create link" :loading="loading" @submit="submit" @change="preview=$event"/><aside class="surface p-5 lg:sticky lg:top-6"><p class="text-xs font-semibold text-text-muted">LIVE PREVIEW</p><div class="mt-5 rounded-lg border border-brand-mid bg-brand-light p-4"><p class="truncate text-base font-semibold text-brand">{{ shortPreview }}</p><p class="mt-1 truncate text-xs text-text-muted">{{ preview.destination_url||'Your destination will appear here' }}</p><span class="mt-3" :class="preview.is_active?'badge-success':'badge-danger'">{{ preview.is_active?'Active':'Disabled' }}</span></div><div class="mt-5 flex justify-center rounded-lg border border-border bg-white p-5"><QrcodeVue :value="shortPreview" :size="150" level="M" render-as="svg"/></div><p class="mt-4 text-xs leading-relaxed text-text-muted">The final short code is allocated by Laravel. QR and copy actions become available after creation.</p></aside></div></div></template>
